### 1. sifli_ap.c - 主要初始化代码

这是黄山派的**核心初始化文件**，负责所有外设的初始化。

#### 关键函数

```c
// 主要初始化函数
int sf32lb52_lchspi_ulp_bringup(void);

// 板级早期初始化
void board_early_initialize(void);

// 板级晚期初始化
void board_late_initialize(void);

// 应用初始化
int board_app_initialize(uintptr_t arg);
```

#### 初始化流程

```c
int sf32lb52_lchspi_ulp_bringup(void)
{
    int ret = OK;

    // 1. 挂载 procfs 文件系统
    mkdir("/proc", 0755);
    nx_mount(NULL, "/proc", "procfs", 0, NULL);

    // 2. 创建 /data 目录并挂载 tmpfs
    mkdir("/data", 0755);
    nx_mount(NULL, "/data", "tmpfs", 0, NULL);

    // 3. 初始化 RTC
    #ifdef CONFIG_RTC
    rtclower = sf32lb_rtc_lowerhalf();
    rtc_initialize(0, rtclower);
    #endif

    // 4. 初始化 ADC
    #ifdef CONFIG_ADC
    sf32lb_adc_init("/dev/adc0");
    #endif

    // 5. 初始化 GPIO
    #ifdef CONFIG_DEV_GPIO
    sifli_gpio_initialize();
    #endif

    // 6. 初始化定时器
    #ifdef CONFIG_TIMER
    sf32lb_timer_initialize(SF32LB_TIMER_DEFAULT_INDEX, 1000000);
    timer_register("/dev/timer0", timer_lower);
    #endif

    // 7. 初始化 PWM
    #ifdef CONFIG_PWM
    sf32lb_pwm_initialize(SF32LB_PWM_DEFAULT_INDEX);
    pwm_register("/dev/pwm0", pwm_lower);
    #endif

    // 8. 初始化按键
    #ifdef CONFIG_INPUT_BUTTONS
    sf32lb52_button_initialize("/dev/buttons");
    #endif

    // 9. 初始化 I2C 总线
    #ifdef CONFIG_I2C
    // I2C0: 触摸屏
    HAL_PIN_Set(PAD_PA37, I2C1_SCL, PIN_PULLUP, 1);
    HAL_PIN_Set(PAD_PA33, I2C1_SDA, PIN_PULLUP, 1);
    i2c0 = sifli_i2cbus_initialize(0);
    i2c_register(i2c0, 0);

    // I2C1: 充电 IC + 传感器
    i2c1 = sifli_i2cbus_initialize(1);
    i2c_register(i2c1, 1);

    // 初始化触摸屏
    ft6146_touch_initialize(i2c0, GET_PIN_2(hwp_gpio1, CONFIG_TOUCH_IRQ_PIN));

    // 初始化 IMU 传感器
    sf32lb52_lsm6ds3_initialize(i2c1);
    #endif

    // 10. 初始化 SPI + TF 卡
    #ifdef CONFIG_SPI
    sf32lb52_spi1_register_char();
    sf32lb52_tfcard_initialize();
    #endif

    // 11. 初始化 LCD（异步）
    #ifdef CONFIG_LCD
    task_create("lcd_async_init", ...);
    #endif

    // 12. 初始化看门狗
    #ifdef CONFIG_WATCHDOG
    sf32lb_iwdginitialize("/dev/watchdog0");
    #endif

    // 13. 挂载 NOR Flash
    #ifdef CONFIG_MTD
    sf32lb_nor_automount(0, SF32LB52_NOR_FS_OFFSET_BLOCKS, SF32LB52_NOR_FS_SIZE_BLOCKS);
    #endif

    // 14. 初始化 USB CDC ACM
    #ifdef CONFIG_CDCACM
    cdcacm_initialize(0, NULL);
    #endif

    // 15. 初始化蓝牙
    #ifdef CONFIG_UART_BTH4
    sf32lb52_bt_initialize();
    #endif

    return ret;
}
```

