#include <nuttx/config.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <nuttx/ioexpander/gpio.h>

#define LED_GPIO_PIN  32  // PA32 - RGB LED

int main(int argc, char *argv[])
{
    int fd;
    bool value = false;

    // 打开 GPIO 设备
    fd = open("/dev/gpio0", O_RDWR);
    if (fd < 0) {
        printf("ERROR: Failed to open GPIO\n");
        return -1;
    }

    // 配置为输出
    ioctl(fd, GPIOC_WRITE, &value);

    // 闪烁 LED
    for (int i = 0; i < 10; i++) {
        value = !value;
        ioctl(fd, GPIOC_WRITE, &value);
        usleep(500000);  // 500ms
    }

    close(fd);
    return 0;
}
```

### 2. I2C 传感器读取示例

```c
#include <nuttx/config.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <nuttx/i2c/i2c_master.h>

#define I2C_DEVICE  "/dev/i2c1"
#define SENSOR_ADDR 0x6A  // LSM6DS3TR-C

int main(int argc, char *argv[])
{
    int fd;
    struct i2c_msg_s msg;
    struct i2c_transfer_s xfer;
    uint8_t reg = 0x0F;  // WHO_AM_I register
    uint8_t data;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        printf("ERROR: Failed to open I2C\n");
        return -1;
    }

    // 读取传感器 ID
    msg.addr = SENSOR_ADDR;
    msg.flags = 0;
    msg.buffer = &reg;
    msg.length = 1;

    xfer.msgv = &msg;
    xfer.msgc = 1;

    ioctl(fd, I2C_TRANSFER, &xfer);

    msg.flags = I2C_M_READ;
    msg.buffer = &data;
    msg.length = 1;

    ioctl(fd, I2C_TRANSFER, &xfer);

    printf("Sensor ID: 0x%02X\n", data);

    close(fd);
    return 0;
}
```

