### 4. 按键读取示例

```c
#include <nuttx/config.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>

int main(int argc, char *argv[])
{
    int fd;
    struct pollfd fds;
    char buffer[1];

    // 打开按键设备
    fd = open("/dev/buttons", O_RDONLY);
    if (fd < 0) {
        printf("ERROR: Failed to open buttons\n");
        return -1;
    }

    printf("Press KEY2 button...\n");

    // 等待按键事件
    fds.fd = fd;
    fds.events = POLLIN;

    while (1) {
        int ret = poll(&fds, 1, -1);
        if (ret > 0 && (fds.revents & POLLIN)) {
            read(fd, buffer, 1);
            printf("Button pressed! Value: %d\n", buffer[0]);
            break;
        }
    }

    close(fd);
    return 0;
}
```

